jQuery(function (e) {
	'use strict';
	e(document).on('click', '.install-etlms-dependency-plugin-button', function (n) {
		n.preventDefault();
		var t = e(this),
			l = t.data('slug'),
			s = t.closest('.etlms-install-notice').find('.etlms-install-notice-msg');
		if (t.hasClass('updating-message')) {
			return;
		}
		e.ajax({
			type: 'POST',
			url: ajaxurl,
			data: {
				slug: l,
				action: 'install_etlms_dependency_plugin',
				nonce: window._etlms_installer ? window._etlms_installer.nonce : '',
			},
			beforeSend: function () {
				(t.addClass('updating-message').attr('aria-disabled', 'true'), s.empty());
			},
			success: function (n) {
				(t.remove(), s.html(n));
			},
			error: function (n) {
				var i = n.responseJSON && n.responseJSON.data,
					o = e('<div class="notice notice-error inline"><p></p></div>');
				o.find('p').text(
					'string' == typeof i && i
						? i
						: (window._etlms_installer && window._etlms_installer.generic_error) ||
								'Installation failed. Please try again.'
				);
				s.append(o);
			},
			complete: function () {
				t.removeClass('updating-message').removeAttr('aria-disabled');
			},
		});
	});
});
